function () {
  var event = {{DLV - canonical_event}};
  var eventName = {{Event}};
  var eventId = {{DLV - event_id}};

  if (!event || !event.event_id ||
      event.event_name !== eventName ||
      event.event_id !== eventId || !event.custom_data) {
    return;
  }

  var source = event.custom_data;
  var result = {};

  var eventFields = [
    'currency', 'value', 'coupon',
    'item_list_id', 'item_list_name',
    'promotion_id', 'promotion_name',
    'creative_name', 'creative_slot'
  ];

  var itemFields = [
    'item_id', 'item_name', 'item_brand', 'item_variant',
    'item_category', 'item_category2', 'item_category3',
    'item_category4', 'item_category5',
    'quantity', 'discount'
  ];

  function copyFields(from, to, fields) {
    for (var i = 0; i < fields.length; i++) {
      var key = fields[i];
      if (from[key] !== undefined && from[key] !== null) {
        to[key] = from[key];
      }
    }
  }

  copyFields(source, result, eventFields);

  if (Array.isArray(source.items)) {
    result.items = source.items.map(function (item) {
      var mapped = {};
      copyFields(item, mapped, itemFields);

      if (typeof item.unit_price === 'number' &&
          isFinite(item.unit_price)) {
        mapped.price = item.unit_price;
      }

      return mapped;
    });
  }

  return result;
}

